/* ══ ★ v135：四季场景图池（四个系列）═══════════════════════════════
   用户稍后给图床链接，直接往下面四个对象里按「场景键」填 URL 即可，
   其余代码一行都不用改；没填的键自动回退到原来的时段图 / 单图。

   场景键（与现有图床一一对应）：
     title                                    标题页背景
     apartment_gate / apartment_hall / apartment_door / park_apartment
     entry / living / kitchen / bath / room_main / room_2nd / storage / balcony
     shop_front / shop_in / park / village_park
     shrine_tunnel / shrine_yard / shrine_hall_in / shrine_guest / shrine_onsen
     shrine_main_room / shrine_main_room_out / shrine_shop_out / shrine_shop_in
     village_yard / village_road / forest_path / forest_shrine / forest_stream
     dam / lumber / village_gate / village_bridge / field_hut
   SEASON_WEATHER_IMGS 是可选的「天气专属图」，优先级更高；
   不给就只用 SEASON_SCENE_IMGS，再没有就走原来的时段图 / 单图。 */
var SEASON_SCENE_IMGS = { '春': {}, '夏': {}, '秋': {}, '冬': {} };
var SEASON_WEATHER_IMGS = {
  '春': { '晴朗': {}, '阴天': {}, '下雨': {} },
  '夏': { '晴朗': {}, '阴天': {}, '下雨': {} },
  '秋': { '晴朗': {}, '阴天': {}, '下雨': {} },
  '冬': { '晴朗': {}, '阴天': {}, '下雨': {} }
};
/* 地点名 → 场景键。复用现有三片区的归一化判断，认不出的归到乡村小路 */
function seasonSceneKeyOf(name) {
  var n = String(name || '').trim();
  if (!n || n.indexOf('开场白') !== -1) return 'title';
  try {
    if (typeof isShrineScene === 'function' && isShrineScene(n)) {
      var sh = (typeof normalizeShrinePlace === 'function' ? normalizeShrinePlace(n) : '') || n;
      var sk = SHRINE_IMG_KEY[sh];
      return sk ? 'shrine_' + sk : 'shrine_yard';
    }
  } catch (e1) {}
  try {
    if (typeof isApartmentScene === 'function' && isApartmentScene(n)) {
      var c = (typeof normalizeApartmentPlace === 'function' ? normalizeApartmentPlace(n) : '') || n;
      if (c.indexOf('便利店') !== -1) return 'apartment_gate';
      if (c.indexOf('对面公园') !== -1) return 'park_apartment';
      /* ══ ★ 2026-11-16：**门外节点「号门」和「号房」都认** ═══════════════
         玩家报「有一些号房的门前全是走廊的图」。
         ★ 2026-11-16 晚：地点名**已全量改成「号门」**（见 TH_MAP_DEF 与
           MAP_TOPOLOGY），但正则里的 `房` **故意留着** —— 老存档的变量里
           存的还是 `公寓3楼走廊-303号房`，删掉就让他们全部掉回走廊图。

         ── 原来错在哪 ──────────────────────────────────────────────────
         这条判断只认 `号门`。而当时公寓的门前地点有两套写法：
           · 2 楼：`公寓2楼走廊-201号门` / `-203号门`   → 命中，给门外图 ✓
           · 3/4 楼：`公寓3楼走廊-303号房` / `-305号房` / `-405号房` / `-407号房`
                                                    → **不命中**，落到下面
                                                      `走廊` 那条 ⇒ 给走廊图 ✗
         于是 6 个门前地点里，2 楼那 2 个对、3/4 楼那 4 个全是走廊。
         玩家说的「有一些号房门前是走廊」，就是这 4 个。

         ── 真正的分界不是「号门 / 号房」────────────────────────────────
         而是「带不带 `室`」：
           · 含 `室`    ⇒ 门内的房间，走下面的户型分支
           · 不含 `室`  ⇒ 门外 / 走廊节点
         所以判据写成「(号门|号房) 且不含 室」，顺序也要排在户型和走廊之前。
         ⚠ 别因为「号房这词已经废了」就把 `房` 从正则里删掉 —— 那是拿
           老存档换来的干净，会当场变成「一升级就全是走廊图」。 */
      if (/(\d{3})\s*号(门|房)/.test(c) && c.indexOf('室') === -1) return 'apartment_door';
      if (c.indexOf('走廊') !== -1) return 'apartment_hall';
      if (c.indexOf('公寓楼下') !== -1) return 'apartment_gate';
      /* ★ 19:12：这里原来写死 301室 —— 201 / 203 / 303 / 305 / 407 全部掉到下面的
         return 'apartment_gate'，于是女主家的客厅、主卧、浴室显示的全是「公寓楼下」
         那张外景。玩家报「公寓篇的房间是不是都没图」，其实是「全贴成了大门口」。
         公寓篇每户户型一样，按「任意三位房号 + 房间类型」复用同一套室内图。 */
      if (/(\d{3})\s*室/.test(c)) {
        var room = c.split('-').pop();
        if (room.indexOf('门口') !== -1) return 'entry';
        if (room.indexOf('客厅') !== -1) return 'living';
        if (room.indexOf('厨房') !== -1) return 'kitchen';
        if (room.indexOf('浴室') !== -1) return 'bath';
        if (room.indexOf('主卧') !== -1) return 'room_main';
        if (room.indexOf('次卧') !== -1) return 'room_2nd';
        if (room.indexOf('杂物') !== -1) return 'storage';
        if (room.indexOf('阳台') !== -1) return 'balcony';
        return 'entry';
      }
      return 'apartment_gate';
    }
  } catch (e2) {}
  if (n.indexOf('小卖铺里') !== -1) return 'shop_in';
  if (n.indexOf('小卖铺前') !== -1) return 'shop_front';
  if (n.indexOf('前院') !== -1) return 'village_yard';
  if (n.indexOf('客厅') !== -1) return 'living';
  if (n.indexOf('厨房') !== -1) return 'kitchen';
  if (n.indexOf('浴室') !== -1) return 'bath';
  if (n.indexOf('主卧') !== -1) return 'room_main';
  if (n.indexOf('次卧') !== -1) return 'room_2nd';
  if (n.indexOf('杂物') !== -1) return 'storage';
  if (n.indexOf('阳台') !== -1) return 'balcony';
  if (n.indexOf('公园') !== -1) return 'village_park';
  if (n.indexOf('废弃大坝') !== -1) return 'dam';
  if (n.indexOf('伐木场') !== -1) return 'lumber';
  if (n.indexOf('村口') !== -1) return 'village_gate';
  if (n.indexOf('庙宇') !== -1) return 'forest_shrine';
  if (n.indexOf('小溪') !== -1) return 'forest_stream';
  if (n.indexOf('田边') !== -1 || n.indexOf('作业小屋') !== -1) return 'field_hut';
  if (n.indexOf('河堤') !== -1 || n.indexOf('桥') !== -1) return 'village_bridge';
  if (n.indexOf('林间') !== -1) return 'forest_path';
  if (n.indexOf('乡村小路') !== -1) return 'village_road';
  return 'village_road';
}
/* ★ 06:00：预加载发生在**入局之前**（玩家刚在开局页选了季节、变量还没写），
   这时 thSeasonOf() 读 stat_data 是空的，只会回落到默认「夏」，
   结果永远预载错季节。这里按优先级找真正选中的那个：
     ① 存档变量 全局.季节（已入局）
     ② 开局页点选时写下的全局/本地值（未入局）
     ③ 默认夏 */
function thSeasonForPreload() {
  var s = '';
  try {
    var sd = getSD() || {};
    s = String((sd.全局 && sd.全局.季节) || '');
  } catch (e0) {}
  if (!/^[春夏秋冬]$/.test(s)) {
    try { s = String(window.__TH_PICK_SEASON__ || (window.top && window.top.__TH_PICK_SEASON__) || ''); } catch (e1) {}
  }
  if (!/^[春夏秋冬]$/.test(s)) {
    try { s = String(localStorage.getItem('thPickSeason') || ''); } catch (e2) {}
  }
  return /^[春夏秋冬]$/.test(s) ? s : '夏';
}

function seasonSceneUrl(name) {
  try {
    /* ★ v155：v146 那批四季图已整批删除（只有季节档、没有时段档，会把
       白天/黄昏/夜晚全盖成同一张）。这里只走旧的分时段图池。 */
    var se = thSeasonOf(), w = thWeatherOf(), k = seasonSceneKeyOf(name);
    var byW = SEASON_WEATHER_IMGS[se] && SEASON_WEATHER_IMGS[se][w];
    if (byW && byW[k]) return byW[k];
    var byS = SEASON_SCENE_IMGS[se];
    if (byS && byS[k]) return byS[k];
  } catch (e) {}
  return '';
}

/* 按时段从一组图里挑一张；缺哪一档就往邻档降级 */
function pickTimeUrl(set) {
  if (!set) return '';
  var b = timeBucket();
  if (b === 'night') return set.night || set.dusk || set.day || '';
  if (b === 'dusk') return set.dusk || set.day || set.night || '';
  return set.day || set.dusk || set.night || '';
}
