/* 按 人物+动作 取一张插图 URL（多图时按动作名做确定性轮换，避免每次刷新都变） */
var _lcsImgIdx = {};
function lcsActImageUrl(charName, actState) {
  try {
    var nm = String(charName || '').trim();
    var act = String(actState || '').trim();
    if (!nm || !act) return '';
    var pool = LCS_ACT_POOL[nm];
    if (!pool) return '';
    /* 动作词容错：把「口交2」「口交3」这类序号先剥掉 */
    var key = act.replace(/\s*\d+$/, '');
    var arr = pool[key] || pool[act];
    if (!arr || !arr.length) return '';
    if (arr.length === 1) return arr[0];
    var sig = nm + '|' + key;
    var i = _lcsImgIdx[sig] || 0;
    _lcsImgIdx[sig] = (i + 1) % arr.length;
    return arr[i];
  } catch (e) { return ''; }
}

