/* 提示键：按存档分。拿不到存档 id 时是 'default'（页面刚加载那一刻属正常，
   那时变量也还没读，读不到提示就当没有，跟以前一样）。 */
function arcHintKey() {
  var id = 'default';
  try { id = currentChatId(); } catch (e) { id = 'default'; }
  return 'thGalLastArc::' + id;
}
/* 第一次读：先读本存档那份；本存档没有，才兼容读一次老键（升级上来的存档不至于丢掉提示）。
   兼容读只是为了让老数据不白丢，写入**只写新键** —— 老键从此不再被更新。 */
try {
  TH_ARC_HINT = localStorage.getItem(arcHintKey()) || '';
  if (!TH_ARC_HINT) TH_ARC_HINT = localStorage.getItem('thGalLastArc') || '';
} catch (eArc0) {}
function thSetArcHint(arc) {
  var a = String(arc || '');
  TH_ARC_HINT = a;
  try { localStorage.setItem(arcHintKey(), a); } catch (e) {}
}


