      var gx = (cx - r.left - TH_MAP_STATE.tx) / TH_MAP_STATE.scale / TH_MAP_CELL;
      var gy = (cy - r.top - TH_MAP_STATE.ty) / TH_MAP_STATE.scale / TH_MAP_CELL;
