/* ══════════════════════════════════════════════════════════════════════
   ★ v148：三栏折叠（顶栏 / 控制舱 / 输入行）+ 功能面板
   ──────────────────────────────────────────────────────────────────────
   用户原话：「把输入栏，按钮栏，顶层全部默认隐藏，需要某些按钮触发，
             并且移植到界面里面，这样子隐藏的时候就可以有更多预览了。
             记得把顶栏和底栏全部去掉，留一个很窄很扁的游戏界面边框就好了。」

   为什么默认折叠：不折叠时 topbar 32px + control-deck（快捷栏 ~26px + 输入行 ~52px）
   常驻吃掉近 100px，而壳本身又按 2844:1600 压 aspect-ratio，玩家实际看到
   画面被上下夹成一条。折叠后舞台 flex 撑满，画面立涨三成以上。

   交互契约：
     · 右上竖条拉手（.th-gal-hud-grip） → 鼠标移入立即展开；点一下也展开
     · 展开后出现顶栏 + 右侧功能面板；面板里放全部快捷按钮 + 输入框
     · 面板右上角 ✕ 收起；2.8 秒无操作且鼠标不在壳内 → 自动收起
     · 玩家在面板底部「📌 常显」里可以关掉自动折叠（存 localStorage）
     · 折叠时左上角一条细字报 时间 · 地点 · 精力（.th-gal-mini-hud）
   ══════════════════════════════════════════════════════════════════════ */
var TH_HUD_KEY = 'thGalHudFold';
/* ★ 18:55 作者要求：功能面板默认**不再自动折叠回去**。
   以前展开后 2.8 秒无操作就自己收，玩家正在找按钮就被抽走，很难受。
   现在默认常显：要收自己点拉手 / ✕。以前主动设过自动折叠（存 '1'）的人仍按他的选择。 */
var _thHudFoldAuto = false;         /* 是否自动折叠（默认关，玩家可开） */
var _thHudTimer = null;
var _thHudBound = false;
/* ★ v163：自动折叠的真正判据。
   ─────────────────────────────────────────────────────────────────────
   v148 的原写法：thHudOpen 挂一个 2800ms 定时器，到点看
     · shell.__thHover（鼠标在不在壳里）
     · 输入框有没有焦点 / 内容
   两个都不满足才收。问题在于 —— **壳就是整个游戏画面**，玩家的鼠标
   几乎永远在壳里（他就在玩游戏）。于是 shell.__thHover 恒为 true，
   每一轮到点都走「重新挂定时器」那条路，永不收起。
   玩家原话：「说好 2.8 秒自动折好，结果压根没反应，还是得手动点 x。」

   现在换成一个语义上说得通的判据：「最后一次**操作**过了多久」。
     · 只有真正碰到了面板（鼠标在面板上 / 输入 / 点按钮）才算操作
     · 鼠标停在画面别处、什么都没干 —— 不算操作，2.8 秒后照收
   用 400ms 心跳检查，而不是递归 setTimeout —— 递归那条路一旦哪一轮
   判错就整条链断掉（v148 就是这样断的），心跳永远在跑，不会断。 */
var _thHudLastAct = 0;              /* 最后一次「真操作」的时刻 */
var TH_HUD_IDLE_MS = 2800;          /* 玩家指定的 2.8 秒 */

/* 记一次操作。面板里任何点击 / 输入 / 鼠标划过都调它。 */
function thHudTouch() { _thHudLastAct = Date.now(); }

function thHudSettingsLoad() {
  try {
    var s = localStorage.getItem(TH_HUD_KEY);
    if (s === '0') _thHudFoldAuto = false;      /* '0' = 玩家要求常显 */
    else if (s === '1') _thHudFoldAuto = true;
  } catch (e) {}
}
function thHudSettingsSave(auto) {
  _thHudFoldAuto = !!auto;
  try { localStorage.setItem(TH_HUD_KEY, auto ? '1' : '0'); } catch (e) {}
}

/* 应用折叠/展开状态。on = true 表示折叠（隐藏三栏、露出拉手）。 */
function thHudApply(shell, folded) {
  if (!shell) return;
  var top = shell.querySelector('.th-gal-shell-topbar');
  var deck = shell.querySelector('.th-gal-control-deck');
  var grip = shell.querySelector('.th-gal-hud-grip');
  var mini = shell.querySelector('.th-gal-mini-hud');
  var panel = shell.querySelector('.th-gal-hud-panel');
  var isFold = !!folded;
  try {
    if (top) top.classList.toggle('is-hid', isFold);
    if (deck) deck.classList.toggle('is-hid', isFold);
    /* ★ v160：拉手常显 —— 折叠时它就是「打开」，展开时它就是「关掉」，不再消失 */
    if (grip) { grip.classList.add('is-on'); grip.classList.toggle('is-open', !isFold); }
    /* ★ v153：mini-hud 现在挂在左上角场景名下面，是**常驻信息块**，
       不再跟折叠状态走（以前只有折叠时才显示，顶栏常隐之后等于常显，
       但代码上还是跟着 isFold 抖，没必要）。 */
    if (mini) mini.classList.add('is-on');
    shell.classList.toggle('is-hud-fold', isFold);
    if (isFold && panel) panel.classList.remove('is-open');
    /* 折叠态下对话框要重新量一次高度（视口变高了） */
    if (typeof fitDialogueStage === 'function') { try { fitDialogueStage(shell); } catch (eR) {} }
  } catch (e) {}
  /* ★ v153：以前只在折叠时同步，现在它是常驻块，每次都要刷 */
  try { syncMiniHud(shell); } catch (eSync) {}
  try { syncStatusCard(shell); } catch (eSync2) {}
}

function thHudOpen(shell) {
  if (!shell) return;
  thHudApply(shell, false);
  var panel = shell.querySelector('.th-gal-hud-panel');
  if (panel) panel.classList.add('is-open');
  /* ★ 2026-11-18：每次打开都刷一次「本局模式」——面板是一次性构建的，
     模式却可能在切篇章 / 读档之后才读准。不刷就会一直显示第一次那个。 */
  try { paintHudMode(); } catch (eGm) {}
  /* ★ v150：每次打开先把镜像按钮的文字刷成最新（季节/天气/音乐可能已变） */
  try { thSyncHudMirror(shell); } catch (eM) {}
  thHudArmAutoClose(shell);
}

function thHudOpenPanelOnly(shell) {
  if (!shell) return;
  var panel = shell.querySelector('.th-gal-hud-panel');
  var deck = shell.querySelector('.th-gal-control-deck');
  var top = shell.querySelector('.th-gal-shell-topbar');
  /* 只开面板，顶栏仍然藏着 —— 玩家想点按钮但不想让顶栏挤画面 */
  if (deck) deck.classList.add('is-hid');
  if (top) top.classList.add('is-hid');
  shell.classList.add('is-hud-fold');
  if (panel) panel.classList.add('is-open');
  try { thSyncHudMirror(shell); } catch (eM) {}
  thHudArmAutoClose(shell);
}

function thHudClose(shell, refold) {
  if (!shell) return;
  var panel = shell.querySelector('.th-gal-hud-panel');
  if (panel) panel.classList.remove('is-open');
  if (refold !== false) thHudApply(shell, true);
}

/* ★ v163：从「挂定时器」改成「记一次操作」。
   名字保留（全卡有 6 处调它），语义变成：玩家刚操作过，重新开始数 2.8 秒。 */
function thHudArmAutoClose(shell) {
  thHudTouch();
  try { if (_thHudTimer) clearTimeout(_thHudTimer); } catch (e) {}
  _thHudTimer = null;
  /* 立刻跑一次心跳，让「刚点完按钮就离开」这种情况不用等下一个 400ms 周期 */
  if (_thHudFoldAuto) thHudIdleTick(shell);
}

/* ★ v163：心跳巡检 —— 面板开着、玩家真的闲着，就收起。
   什么算「闲着」：
     · 鼠标不在面板上（停在画面别处不算操作）
     · 输入框没焦点、也没内容
     · 没有别的全屏弹层压在上面（地图 / 村历 / 立绘 / 角色菜单 / 背包）
   什么算「在用」：
     · 鼠标在面板范围内（panel.__thHover）
     · 输入框有焦点或已输入文字
   在用的时候把 _thHudLastAct 顶到现在 —— 也就是「一直有人碰，就一直不收」。 */
function thHudIdleTick(shell) {
  if (!shell || !_thHudFoldAuto) return false;
  var doc = getDoc();
  var panel = shell.querySelector('.th-gal-hud-panel');
  if (!panel || !panel.classList.contains('is-open')) return false;

  /* 有别的大弹层开着 → 不动面板（玩家在那边办事，回头还要用面板） */
  try {
    var blocking = doc.querySelector(
      '.th-gal-mapmodal:not([hidden]), .th-gal-calmodal:not([hidden]),' +
      '#th-gal-standmodal, #th-gal-switchmodal, .th-gal-char-menu:not([hidden]), .th-gal-sheet:not([hidden])'
    );
    if (blocking) { thHudTouch(); return false; }
  } catch (eB) {}

  /* 鼠标在面板上 = 在用 */
  if (panel.__thHover) { thHudTouch(); return false; }

  /* 打字中 = 在用 */
  var ta = panel.querySelector('.th-gal-hud-textarea');
  try {
    if (ta && (doc.activeElement === ta || String(ta.value || '').trim())) {
      thHudTouch();
      return false;
    }
  } catch (eT) {}

  if (Date.now() - _thHudLastAct < TH_HUD_IDLE_MS) return false;
  thHudClose(shell, true);
  return true;
}

/* ══ ★ 2026-11-18：功能面板顶部的「本局模式」胶囊 ══
   作者要求：「牛头模式新增显示在功能页和左上角玩家面板 ui」。
   ⚠ 唯一数据源 = thGameModeNow()，这里**只负责画**，不自己判一次模型。
     左上角状态卡（syncStatusCard）里那段也读同一个函数 —— 两处显示必然一致。 */
function paintHudMode() {
  try {
    var el = getDoc().getElementById('th-hud-mode');
    if (!el) return;
    /* ★ 2026-11-21：纯爱模式下架 —— 这个胶囊恒显示牛头，不再按变量分叉。 */
    el.textContent = '🐂 牛头模式';
    el.style.borderColor = 'rgba(226,152,66,.62)';
    el.style.background = 'rgba(180,96,20,.22)';
    el.style.color = '#ffd9a8';
    el.title = '本局模式：牛头模式（夏越村与幸福公寓的苦主生效，按四阶段推进；小孩也算苦主）';
  } catch (e) {}
}

/* 把顶栏 + 控制舱里的按钮克隆进功能面板 */
/* ══ 玩家头像：上传 → 中心方形裁切 → 256×256 → localStorage ══════════════
   存的是 dataURL（约 20~40KB），不依赖任何图床；左上角状态卡直接当背景用。 */
/* ★ 2026-11-20：状态卡折叠（状态存 SPR_CARD_FOLD） */
function thApplyCardFold() {
  try {
    var card = getDoc().getElementById('th-gal-status-card');
    if (!card) return;
    var folded = false;
    try { folded = localStorage.getItem('SPR_CARD_FOLD') === '1'; } catch (e0) {}
    card.classList.toggle('is-folded', folded);
    var b = card.querySelector('.ts-fold');
    if (b) {
      b.textContent = folded ? '›' : '‹';
      b.title = folded ? '展开状态面板' : '收起状态面板';
    }
  } catch (e) {}
}
function thBindCardFold() {
  try {
    var card = getDoc().getElementById('th-gal-status-card');
    if (!card) return;
    function toggleFold(e) {
      try { e.stopPropagation(); e.preventDefault(); } catch (e0) {}
      var next = !card.classList.contains('is-folded');
      try { localStorage.setItem('SPR_CARD_FOLD', next ? '1' : '0'); } catch (e1) {}
      thApplyCardFold();
    }
    var b = card.querySelector('.ts-fold');
    if (b && !b.__thFoldBound) { b.__thFoldBound = true; b.onclick = toggleFold; }
    if (!card.__thFoldBound) { card.__thFoldBound = true; card.onclick = toggleFold; }
    thApplyCardFold();
  } catch (e) {}
}

function thApplyAvatar() {
  try {
    var card = getDoc().getElementById('th-gal-status-card');
    if (!card) return;
    var av = card.querySelector('.ts-avatar');
    if (!av) return;
    var url = '';
    try { url = String(HOST.localStorage.getItem('SPR_AVATAR') || ''); } catch (e1) {}
    if (!url) url = String(localStorage.getItem('SPR_AVATAR') || '');
    if (url) {
      av.style.backgroundImage = 'url("' + url + '")';
      av.style.backgroundSize = 'cover';
      av.style.backgroundPosition = 'center';
      var q = av.querySelector('.ts-avatar-q');
      if (q) q.style.display = 'none';
    } else {
      av.style.backgroundImage = '';
      var q2 = av.querySelector('.ts-avatar-q');
      if (q2) q2.style.display = '';
    }
  } catch (e) {}
}
/* ══ 对话框样式 + 透明度（五套皮肤）════════════════════════
   存 localStorage：SPR_DLG_SKIN (0~4) / SPR_DLG_BG_A / SPR_DLG_TXT_A
   全部写成一个函数，任何入口（面板 / 开局）都走它——不允许第二份实现。 */
function thDlgLook() {
  var o = { skin: 0, bg: 0.76, txt: 1 };
  try {
    var sk = parseInt(localStorage.getItem('SPR_DLG_SKIN') || '0', 10);
    if (!isNaN(sk) && sk >= 0 && sk <= 4) o.skin = sk;
    var b = parseFloat(localStorage.getItem('SPR_DLG_BG_A') || '');
    if (!isNaN(b)) o.bg = Math.min(1, Math.max(0.15, b));
    var t = parseFloat(localStorage.getItem('SPR_DLG_TXT_A') || '');
    if (!isNaN(t)) o.txt = Math.min(1, Math.max(0.2, t));
  } catch (e) {}
  return o;
}
function thApplyDlgLook() {
  try {
    var o = thDlgLook();
    var st = getDoc().querySelector('.th-gal-dialogue-stage');
    if (st) {
      st.setAttribute('data-dlgs', String(o.skin));
      /* 底色透明度：只改 background-color，渐变与模糊全留着 */
      st.style.setProperty('background-color', 'rgba(18, 16, 22, ' + o.bg + ')', 'important');
    }
    var bodyEl = getDoc().querySelector('.th-gal-dialogue-body');
    if (bodyEl) bodyEl.style.setProperty('--th-dlg-txt-a', String(o.txt));
    var n1 = getDoc().getElementById('th-alpha-bg');
    if (n1) n1.textContent = Math.round(o.bg * 100) + '%';
    var n2 = getDoc().getElementById('th-alpha-txt');
    if (n2) n2.textContent = Math.round(o.txt * 100) + '%';
    var n3 = getDoc().getElementById('th-alpha-both');
    if (n3) n3.textContent = Math.round(((o.bg + o.txt) / 2) * 100) + '%';
    var nm = getDoc().getElementById('th-dlgs-name');
    if (nm) nm.textContent = '当前：' + ['默认', '双层金线', '樱花压边', '厚描边', '金框樱花'][o.skin];
  } catch (e) {}
}
/* ══ 对话框边上那颗⚙：字体 ±1 / 框高 ±1 / 样式 / 三个透明度 ══════
   数据全部走同一批 localStorage key（和功能页那套完全共用）——两处永远一致。 */
function thDlgNum(key, dflt, min, max) {
  var v = parseFloat(localStorage.getItem(key) || '');
  if (isNaN(v)) v = dflt;
  return Math.min(max, Math.max(min, v));
}
/* ★ 2026-11-24：UI 模式判定 —— 文字版（SPR_UNIFIED_MODE==='text'）时 10-core 只跑
   变量检测 / 补全中心 / 版本显示 / 正文美化铺满，**不造游戏壳**（壳是游戏版的界面）。 */
function thUiIsTextMode() {
  try {
    var w = (window.top && window.top.localStorage) ? window.top : window;
    return String(w.localStorage.getItem('SPR_UNIFIED_MODE')) === 'text';
  } catch (e) { return false; }
}

/* ══ ★ 2026-11-24（作者）：插图屏蔽 / 立绘屏蔽 ═══════════════════════════
   游戏版按钮栏一颗「🚫 插图屏蔽」；文字版在功能页多一颗「立绘屏蔽」。
   插图屏蔽 = 外置（智绘姬）+ 内置图组 + 正文里的插图全部不显示；
   立绘屏蔽 = 壳里的 .th-gal-standing-img（现场立绘层 + 说话立绘层）全部不显示。 */
function thIllustBlockOn() {
  try {
    var v = null;
    try { v = localStorage.getItem('SPR_ILLUST_BLOCK'); } catch (e1) {}
    if (v == null) { try { v = HOST.localStorage.getItem('SPR_ILLUST_BLOCK'); } catch (e2) {} }
    return v === '1';
  } catch (e) { return false; }
}
function thSpriteBlockOn() {
  try {
    var v = null;
    try { v = localStorage.getItem('SPR_SPRITE_BLOCK'); } catch (e1) {}
    if (v == null) { try { v = HOST.localStorage.getItem('SPR_SPRITE_BLOCK'); } catch (e2) {} }
    return v === '1';
  } catch (e) { return false; }
}
function thPaintIllustBlockUI() {
  try {
    var d = getDoc();
    var ib = d && d.querySelector('.th-gal-btn-illust-block');
    if (ib) {
      var onI = thIllustBlockOn();
      ib.textContent = '🚫 插图屏蔽：' + (onI ? '开' : '关');
      ib.classList.toggle('is-on', onI);
    }
    var b1 = d && d.querySelector('[data-illblock]');
    if (b1) b1.textContent = thIllustBlockOn() ? '🚫 开' : '关';
    var b2 = d && d.querySelector('[data-spriteblock]');
    if (b2) b2.textContent = thSpriteBlockOn() ? '🚫 开' : '关';
  } catch (e) {}
}
function thApplyIllustBlock() {
  try {
    var d = getDoc();
    if (d && d.body && d.body.classList) d.body.classList.toggle('spr-sprite-blocked', thSpriteBlockOn());
    /* 立绘屏蔽：一条 CSS 管住两个立绘层（现场层与说话层都是 .th-gal-standing-img） */
    try {
      var st = d && d.getElementById('th-spr-block-css');
      if (thSpriteBlockOn()) {
        if (!st) {
          st = d.createElement('style');
          st.id = 'th-spr-block-css';
          st.textContent = '.spr-sprite-blocked .th-gal-standing-img{display:none!important;}';
          (d.head || d.documentElement).appendChild(st);
        }
      } else if (st && st.parentNode) { st.parentNode.removeChild(st); }
    } catch (eCss) {}
    /* 通知 gal 立即重画（内置 CG 与外置插图两条都收） */
    try { if (window.__sprGalRepaint) window.__sprGalRepaint(); } catch (eRp) {}
    thPaintIllustBlockUI();
  } catch (e) {}
}
try { window.thIllustBlockOn = thIllustBlockOn; } catch (eIB1) {}
try { window.thSpriteBlockOn = thSpriteBlockOn; } catch (eIB2) {}
try { window.thApplyIllustBlock = thApplyIllustBlock; } catch (eIB3) {}

function thApplyDlgSize() {
  try {
    var fs = thDlgNum('SPR_DLG_FS', 12, 9, 22);
    var hh = thDlgNum('SPR_DLG_H', 0, 0, 560);   /* 0 = 用默认比例；上限 560 —— 以前写成 0,0 把玩家调的值钳成 0，按钮永远没反应 */
    var st = getDoc().querySelector('.th-gal-dialogue-stage');
    var bodyEl = getDoc().querySelector('.th-gal-dialogue-body');
    var o0 = thDlgLook();
    /* ★ 2026-11-19：**不改全局样式表**，只对当前这个元素写 inline !important（优先级最高）。
       上一版我在样式表尾巴加了全局覆盖，结果把整个 gal 壳的排版带崩了 —— 不该那么干。 */
    if (st) {
      /* ★ 2026-11-19：作者「对话框一直鬼畜，疯狂上下变高变矮」。
         真因：这里每次都写 height，而排版那边每帧也在重算高度 ⇒ 两边互相抢，上下抖。
         现在：**同一个数值只写一次**，且用一个标记告诉排版「这个框高是玩家手调的」。 */
      if (hh > 0) {
        var px = Math.round(hh);
        if (st.getAttribute('data-th-dlgh') !== String(px)) {
          st.setAttribute('data-th-dlgh', String(px));
          st.style.setProperty('height', px + 'px', 'important');
        }
      } else if (st.hasAttribute('data-th-dlgh')) {
        st.removeAttribute('data-th-dlgh');
        st.style.removeProperty('height');
      }
    }
    if (bodyEl) {
      bodyEl.style.setProperty('font-size', 'calc(' + fs + 'px * var(--ui-scale, 1))', 'important');
      bodyEl.style.setProperty('color', 'rgba(247, 242, 232, ' + o0.txt + ')', 'important');
    }
    var fEl = getDoc().getElementById('th-dlg-fs-val');
    if (fEl) fEl.textContent = fs + 'px';
    var hEl = getDoc().getElementById('th-dlg-h-val');
    if (hEl) hEl.textContent = hh > 0 ? (Math.round(hh) + 'px') : '自动';
  } catch (e) {}
}
