      try { localStorage.removeItem('thGalPendingSeason'); } catch (ePsr) {}
      try { localStorage.removeItem('thGalPendingArt'); } catch (ePar) {}
      try { localStorage.removeItem('thGalPendingStartType'); } catch (ePstr) {}
      try { localStorage.removeItem('thGalPendingPlayerInfo'); } catch (ePpir) {}
      var pArc = normArc(pendingArc);
      var pMode = thNormGameMode(pendingMode);
      var pSeason = thNormSeason(pendingSeason);
      var pArt = thNormArt(pendingArt);
      var pST = thNormStartType(pendingStartType);
      var pPI = thNormPlayerInfo(pendingPlayerInfo);
      thSetGameMode(pMode, { skipPeerSync: true });
      thSetSeason(pSeason, true);
      thSetArt(pArt);
      thSetStartType(pST);
      thSetPlayerInfo(pPI);
