    + 'background:rgba(0,0,0,.45);border:1px solid rgba(190,160,255,.3);border-radius:6px;'
    + 'font-size:10px;line-height:1.55;color:#cfc6e8;white-space:pre-wrap;word-break:break-all;"></pre>';
