        + ' <button type="button" id="th-wb-restore" style="margin-left:6px;padding:2px 9px;border-radius:999px;'
        + 'border:1px solid rgba(125,211,252,.5);background:rgba(30,58,95,.55);color:#cfe6ff;font-size:11px;'
